"""Long-form multilingual article data for the authority hub.

The original six routes are upgraded in place so their early search signals are
preserved. Seven additional routes cover the remaining requested search intents
without publishing near-duplicate pages.
"""

from __future__ import annotations


def article(
    slug,
    title,
    seo_title,
    summary,
    category,
    cluster,
    tags,
    sections,
    checklist,
    closing,
    faq,
    related,
    published="2026-08-05",
    modified="2026-08-05",
    reading=None,
    featured=False,
):
    return {
        "slug": slug,
        "title": title,
        "seo_title": seo_title,
        "summary": summary,
        "category": category,
        "cluster": cluster,
        "tags": tags,
        "sections": sections,
        "checklist": checklist,
        "closing": closing,
        "faq": faq,
        "related": related,
        "published": published,
        "modified": modified,
        "reading": reading or {"en": "8 min read", "pt": "8 min de leitura", "es": "8 min de lectura"},
        "featured": featured,
    }


def compact(*, slug, title, summary, category, cluster, tags, content, checklist, closing, faq, related, published="2026-08-05", modified="2026-08-05", featured=False):
    return article(
        slug,
        title,
        {lang: f"{value} | Luiz Terra" for lang, value in title.items()},
        summary,
        category,
        cluster,
        tags,
        {lang: [(heading, [paragraph]) for heading, paragraph in sections] for lang, sections in content.items()},
        checklist,
        closing,
        faq,
        related,
        published=published,
        modified=modified,
        featured=featured,
    )


